OOR AHMED"],[1029,"BAJK","SHABBIR AHMED BUTT","8220112486721",null,"AJK","Bank of AJK","20520001",null,0,"040",null,"ABDULLAH BUTT"],[1030,"BAJK","SHAH MUHAMMAD","8220311686633",null,"AJK","Bank of AJK","26164001",null,0,"028",null,"SHAHZAMAN"],[1031,"BAJK","MUHAMMAD AKRAM","8220360931313",null,"AJK","Bank of AJK","26042001",null,0,"001",null,"MUHAMMAD ZAMAN"],[1032,"BAJK","SADAQAT GILLANI","8220350759567",null,"AJK","Bank of AJK","13283001",null,0,"061",null,"MUNAWAR HUSSAIN SHAH"],[1033,"BAJK","SAJJAD AHMED LONE","822036906924",null,"AJK","Bank of AJK","11502001",null,0,"061",null,"HAJI HABIBULLAH LONE"],[1034,"BAJK","MANGTA KHAN","8220103946421",null,"AJK","Bank of AJK","18247001",null,0,"040",null,"SHEER MUHAMMAD"],[1035,"BAJK","GHULAM MUHAMMAD","8220188722435",null,"AJK","Bank of AJK","16640001",null,0,"052",null,"SATTAR MUHAMMAD"],[1036,"BAJK","SHERAZ AHMED AWAN","8220375385959",null,"AJK","Bank of AJK","15580001",null,0,"061",null,"MUHAMMAD AYUB KHAN"],[1037,"BAJK","M MAQBOOL","4250165814447",null,"AJK","Bank of AJK","25697001",null,0,"001",null,"DOST MUHAMMAD"],[1038,"BAJK","MUHAMMAD ANSER","8220310514709",null,"AJK","Bank of AJK","10025001",null,0,"077",null,"MUHAMMAD SAIN"],[1039,"BAJK","M. ASLAM","1350112910089",null,"AJK","Bank of AJK","10378001",null,0,"070",null,"QUSMATULLAH"],[1040,"BAJK","QAMAR UD DIN","8220336329263",null,"AJK","Bank of AJK","14581001",null,0,"053",null,"AKHTER SAEED"],[1041,"BAJK","M. ISMAIL","8220371140271",null,"AJK","Bank of AJK","12148001",null,0,null,null,"MIR MUHAMMAD"],[1042,"BAJK","M. AFZAL","8220135211343",null,"AJK","Bank of AJK","15397001",null,0,"052",null,"M. HUSSAIN"],[1043,"BAJK","KHALIL UR REHMAN","8220123389761",null,"AJK","Bank of AJK","PLS-496",null,0,"0076",null,"ABDUL REHMAN"],[1044,"BAJK","M KHURSHEED","8220123448295",null,"AJK","Bank of AJK","11427001",null,0,"052",null,"M. YASEEN"],[1045,"BAJK","AURANGZEB","8220197472413",null,"AJK","Bank of AJK","CD-2128",null,0,"0043",null,"MUHAMMAD ZAMAN KHAN"],[1046,"BAJK","Dilbar Khan","8220123489821",null,"AJK","Bank of AJK","15787001",null,0,"028",null,"Jumma Khan"],[1047,"BAJK","FAZAL UR REHMAN","8220262054027",null,"AJK","Bank of AJK","10005001",null,0,null,null,"ATTA MUHAMMAD"],[1048,"BAJK","RASHID SARWAR","8220123388189",null,"AJK","Bank of AJK","26197001",null,0,"001",null,"KHAN GUL"],[1049,"BAJK","MUHAMMAD SULTAN SHEIKH","8220159760433",null,"AJK","Bank of AJK","12608001",null,0,"5067",null,"ANBDULLAH SHEIKH"],[1050,"BAJK","GUL HASSAN","8220368830591",null,"AJK","Bank of AJK","15182001",null,0,null,null,"WALI UR REHMAN"],[1052,"BAJK","FAHEEM ABBASI","8220379260165",null,"AJK","Bank of AJK","11733001",null,0,"039",null,"MUSHTAQ AHMED"],[1053,"BAJK","MOHSIN ARIF","3740569756497",null,"AJK","Bank of AJK","21641001",null,0,null,null,"M. ARIF JANJUA"],[1054,"BAJK","SYED SAJID HUSSAIN KAZMI","8270103414731",null,"AJK","Bank of AJK","14782001",null,0,"061",null,"SYED GHULAM HUSSAIN KAZMI"]]';
  v_filled int; v_same int; v_conflict int; v_unmatched int; v_bad int;
begin
  create temp table _imp on commit drop as
  select (x->>0)::int ref, x->>1 src, x->>2 name, nullif(x->>3, '') cnic, nullif(x->>4, '') sid, x->>5 hint,
         x->>6 bank, x->>7 acct, nullif(x->>8, '') iban, (x->>9)::int = 1 iban_generated, nullif(x->>10, '') branch,
         nullif(x->>11, '') holder, nullif(x->>12, '') father,
         btrim(regexp_replace(regexp_replace(regexp_replace(lower(regexp_replace(x->>2, '\([^)]*\)', '', 'g')),
           '\m(m|mohammad|muhammed|mohd|muhammad)\M\.?', 'muhammad', 'g'), '[^a-z ]', ' ', 'g'), '\s+', ' ', 'g')) nn
    from jsonb_array_elements(v_rows) x;

  create temp table _emp on commit drop as
  select e.id, e.full_name, e.status in ('Active', 'On Leave') act, e.category::text cat, e.legacy_code, c.name client,
         regexp_replace(coalesce(e.cnic_number, ''), '\D', '', 'g') cnic,
         btrim(regexp_replace(regexp_replace(regexp_replace(lower(regexp_replace(e.full_name, '\([^)]*\)', '', 'g')),
           '\m(m|mohammad|muhammed|mohd|muhammad)\M\.?', 'muhammad', 'g'), '[^a-z ]', ' ', 'g'), '\s+', ' ', 'g')) nn,
         e.bank_name, e.account_title, e.bank_account, e.iban, e.bank_branch_code, e.cnic_number, e.father_or_husband_name
    from public.employees e left join public.clients c on c.id = e.client_id
   where e.company_id = v_co and (e.lifecycle_state is null or e.lifecycle_state::text not in ('applicant', 'waitlisted'));

  -- Match: CNIC, then sheet ID, then a name unique under the sheet's client.
  create temp table _m on commit drop as
  with by_cnic as (select distinct on (r.ref) r.ref, e.id from _imp r join _emp e on r.cnic is not null and length(r.cnic) = 13 and e.cnic = r.cnic order by r.ref, e.act desc),
       by_sid as (select distinct on (r.ref) r.ref, e.id from _imp r join _emp e on r.sid is not null and e.legacy_code = r.sid order by r.ref, e.act desc),
       cand as (select r.ref, e.id from _imp r join _emp e on e.act and e.nn = r.nn
                 where case when r.hint = 'HO' then e.cat = 'office_staff' when r.hint = 'Reliever' then e.cat = 'reliever'
                            else coalesce(e.client, '') ilike '%' || r.hint || '%' end),
       by_name as (select ref, (array_agg(id))[1] id from cand group by ref having count(*) = 1)
  select r.*, coalesce(c.id, s.id, n.id) emp_id
    from _imp r left join by_cnic c on c.ref = r.ref left join by_sid s on s.ref = r.ref left join by_name n on n.ref = r.ref;

  -- One sheet account per employee; two rows for one person must agree.
  create temp table _plan on commit drop as
  with k as (
    select m.*, ltrim(case when m.acct ~ '^[A-Z]+-' then m.acct else regexp_replace(m.acct, '\D', '', 'g') end, '0') ka
      from _m m where m.emp_id is not null),
  per as (select emp_id, count(distinct ka) n_acct from k group by emp_id)
  select distinct on (k.emp_id) k.*, p.n_acct, e.full_name,
         ltrim(case when e.bank_account ~* 'PK\d{2}[A-Z]{4}' then substring(upper(regexp_replace(e.bank_account, '\s', '', 'g')) from 'PK\d{2}[A-Z]{4}(\d{16})')
                    when e.bank_account ~ '^[A-Z]+-' then e.bank_account
                    else regexp_replace(coalesce(e.bank_account, ''), '\D', '', 'g') end, '0') ke,
         e.bank_account old_acct, upper(regexp_replace(coalesce(e.iban, ''), '\s', '', 'g')) old_iban
    from k join per p on p.emp_id = k.emp_id join _emp e on e.id = k.emp_id
   order by k.emp_id, k.ref;
  alter table _plan add column action text;
  update _plan set action = case when n_acct > 1 then 'conflict: two different accounts on the sheets'
                                 when coalesce(ke, '') = '' then 'fill'
                                 when ke = ka then 'same'
                                 when iban is not null and old_iban = iban then 'same'
                                 else 'conflict: Bastion holds ' || old_acct end;

  create temp table _before on commit drop as select * from public.employees where id in (select emp_id from _plan);

  update public.employees e set
    bank_name        = coalesce(nullif(btrim(e.bank_name), ''), p.bank),
    account_title    = coalesce(nullif(btrim(e.account_title), ''), coalesce(p.holder, e.full_name)),
    bank_account     = coalesce(nullif(btrim(e.bank_account), ''), p.acct),
    iban             = coalesce(nullif(btrim(e.iban), ''), p.iban),
    bank_branch_code = coalesce(nullif(btrim(e.bank_branch_code), ''), p.branch),
    cnic_number      = coalesce(nullif(btrim(e.cnic_number), ''),
                         case when p.src = 'BAJK' and length(p.cnic) = 13
                               and not exists (select 1 from public.employees o where o.company_id = v_co and o.id <> e.id
                                                and regexp_replace(coalesce(o.cnic_number, ''), '\D', '', 'g') = p.cnic)
                              then substr(p.cnic, 1, 5) || '-' || substr(p.cnic, 6, 7) || '-' || substr(p.cnic, 13, 1) end),
    father_or_husband_name = coalesce(nullif(btrim(e.father_or_husband_name), ''), case when p.src = 'BAJK' then initcap(lower(p.father)) end)
  from _plan p
  where e.id = p.emp_id and p.action in ('fill', 'same')
    and (nullif(btrim(e.bank_name), '') is null or nullif(btrim(e.account_title), '') is null or nullif(btrim(e.bank_account), '') is null
         or (nullif(btrim(e.iban), '') is null and p.iban is not null) or (nullif(btrim(e.bank_branch_code), '') is null and p.branch is not null)
         or (p.src = 'BAJK' and (nullif(btrim(e.cnic_number), '') is null or nullif(btrim(e.father_or_husband_name), '') is null)));

  -- Every employee planned for writing now holds the sheet's account.
  select count(*) into v_bad from _plan p join public.employees e on e.id = p.emp_id
   where p.action in ('fill', 'same')
     and ltrim(case when e.bank_account ~* 'PK\d{2}[A-Z]{4}' then substring(upper(regexp_replace(e.bank_account, '\s', '', 'g')) from 'PK\d{2}[A-Z]{4}(\d{16})')
                    when e.bank_account ~ '^[A-Z]+-' then e.bank_account else regexp_replace(e.bank_account, '\D', '', 'g') end, '0') <> p.ka
     and not (p.iban is not null and upper(regexp_replace(coalesce(e.iban, ''), '\s', '', 'g')) = p.iban);
  if v_bad <> 0 then raise exception '0603 REFUSED: % employees do not hold the sheet''s account afterwards.', v_bad; end if;
  -- No conflicted employee changed.
  select count(*) into v_bad from _plan p join public.employees e on e.id = p.emp_id join _before b on b.id = e.id
   where p.action like 'conflict%' and row(e.*) is distinct from row(b.*);
  if v_bad <> 0 then raise exception '0603 REFUSED: % conflicted employees changed.', v_bad; end if;
  -- No field that held a value holds a different one.
  select count(*) into v_bad from public.employees e join _before b on b.id = e.id
   where (nullif(btrim(b.bank_name), '') is not null and e.bank_name is distinct from b.bank_name)
      or (nullif(btrim(b.account_title), '') is not null and e.account_title is distinct from b.account_title)
      or (nullif(btrim(b.bank_account), '') is not null and e.bank_account is distinct from b.bank_account)
      or (nullif(btrim(b.iban), '') is not null and e.iban is distinct from b.iban)
      or (nullif(btrim(b.bank_branch_code), '') is not null and e.bank_branch_code is distinct from b.bank_branch_code)
      or (nullif(btrim(b.cnic_number), '') is not null and e.cnic_number is distinct from b.cnic_number)
      or (nullif(btrim(b.father_or_husband_name), '') is not null and e.father_or_husband_name is distinct from b.father_or_husband_name);
  if v_bad <> 0 then raise exception '0603 REFUSED: % employees had a filled field overwritten.', v_bad; end if;
end $import$;
